 def layout(content,toc):
  return f'''<div class="reading-layout"><aside class="contents"><nav aria-label="{tr('Содержание страницы','On this page')}"><p>{tr('Содержание','Contents')}</p>{''.join(a('#'+id,label) for id,label in toc)}</nav></aside><div class="article-body">{content}</div></div>'''
 bio=tr('Я физик, работаю в лаборатории оксидной электроники ИРЭ РАН. Исследую плёнки SrIrO₃ и Sr₂IrO₄: выращиваю образцы, изучаю их структуру и измеряю электрические свойства. Отдельная часть работы — гетероструктуры с магнитными и сверхпроводящими слоями.','I am a physicist at the oxide electronics laboratory of IRE RAS. I grow SrIrO₃ and Sr₂IrO₄ films, study their structure and measure their electrical properties. My work also includes heterostructures with magnetic and superconducting layers.')
 if page=='home':
  hero=f'''<section class="hero" id="about"><div class="hero-copy"><p class="eyebrow">{tr('Физик · ИРЭ РАН · Москва','Physicist · IRE RAS · Moscow')}</p><h1>{t['name']}</h1><p class="other-name">{t['other']}</p><p class="hero-line">{tr('Иридаты стронция: структура, транспорт, спинтроника','Strontium iridates: structure, transport, spintronics')}</p><p>{bio}</p><div class="actions">{a(path(lang,'research'),t['explore'],'button')}{a('mailto:'+EMAIL,tr('Написать мне ↗','Email me ↗'))}</div></div><aside class="profile-panel"><figure class="hero-portrait"><img src="/assets/nikita-dubitskiy.jpg" width="1254" height="1254" alt="{t['name']} — {tr('физик','physicist')}" fetchpriority="high"></figure><dl class="profile-facts"><div><dt>{tr('Работа','Work')}</dt><dd>{lab()}</dd></div><div><dt>{tr('Материалы','Materials')}</dt><dd>SrIrO₃ · Sr₂IrO₄</dd></div><div><dt>{tr('Образование','Education')}</dt><dd>{tr('РТУ МИРЭА → НИУ ВШЭ','MIREA → HSE University')}</dd></div></dl><div class="profile-links">{''.join(a(v,k+' ↗') for k,v in list(profiles.items())[:3])}</div></aside></section>'''
  research=materials(lang)+'<p class="figure-key">'+a("https://pmc.ncbi.nlm.nih.gov/articles/PMC7431029/","SrIrO₃: Nan et al., 2019 / 2020 ↗")+" · "+a("https://arxiv.org/abs/0803.2927","Sr₂IrO₄: Kim et al., 2008 ↗")+'</p>'+f'<p class="research-summary">{tr("Я изучаю, как свойства этих материалов зависят от толщины плёнки, подложки и условий роста. В SrIrO₃ меня интересуют электронный и магнитный транспорт, в Sr₂IrO₄ — механизмы проводимости и использование в джозефсоновских структурах.","I study how film thickness, substrate and growth conditions affect these materials. My work on SrIrO₃ concerns electronic and magnetotransport; on Sr₂IrO₄, conduction mechanisms and Josephson structures.")}</p>'+a(path(lang,'research'),tr('Мои исследования →','My research →'))
  selected=''.join(f'<article class="selected-work"><span>{p["year"]} · {esc(p["journal"])}</span><h3>{a(p["url"],esc(p["ru_title"] if ru else p["title"]))}</h3></article>' for p in [papers[0],papers[8],papers[2]])
  content=hero+section('materials',tr('Иридаты стронция','Strontium iridates'),research)+section('devices',tr('Зачем это спинтронике','Why it matters for spintronics'),devices(lang,a))+section('papers',t['selected'],selected+a(path(lang,'publications'),t['allpapers']+' →'))+f'<div class="home-end"><p>{a(path(lang,"cv"),tr("Биография и CV","Biography & CV"))} · {a(path(lang,"conferences"),tr("Конференции","Conferences"))} · {a(NTO,tr("Обо мне: «Факел НТО» ↗","My profile: Fakel NTO ↗"))}</p><p>{a(path(lang,"contact"),tr("Обсудить исследование или задать вопрос →","Discuss research or ask a question →"))}</p></div>'
  return layout(content,[('about',tr('Обо мне','About')),('materials',tr('Материалы','Materials')),('devices',tr('Спинтроника','Spintronics')),('papers',t['nav'][2])])
 heading=lambda title,intro:f'<header class="page-heading"><p class="eyebrow">{t["name"]}</p><h1>{title}</h1><p class="lead">{intro}</p></header>'
 if page=='research':
  topics=[
   ('SrIrO₃: рост и электронный транспорт','SrIrO₃: growth and electronic transport','В работах по SrIrO₃ я исследую влияние подложки, толщины и условий напыления на структуру и проводимость плёнок. Сопоставляю рентгеновские данные с измерениями сопротивления, магнитосопротивления и эффекта Холла. Серия на пяти подложках, вошедшая в магистерскую диссертацию, — одна из частей этой работы.','My SrIrO₃ research examines how substrate, thickness and deposition conditions affect film structure and conduction. I relate X-ray measurements to resistance, magnetoresistance and the Hall effect. The five-substrate series in my master’s thesis is one part of this work.',papers[4]['url']),
   ('Sr₂IrO₄: структура и механизмы проводимости','Sr₂IrO₄: structure and conduction mechanisms','Для плёнок Sr₂IrO₄ мы сравнивали способы получения и исследовали температурную зависимость проводимости. В этих работах рассматриваются термоактивационный и прыжковый перенос заряда, а также связь электрических свойств со структурой образцов.','For Sr₂IrO₄ films, we compared deposition methods and investigated temperature-dependent conduction. These studies address thermally activated and hopping transport and their relationship to sample structure.',papers[8]['url']),
   ('Иридаты в сверхпроводящих гетероструктурах','Iridates in superconducting heterostructures','В совместных работах мы исследуем перенос тока через прослойки SrIrO₃ и Sr₂IrO₄ в джозефсоновских структурах. Здесь важны свойства самого барьера, его толщина и границы со сверхпроводящими электродами.','In collaborative studies, we investigate current transport through SrIrO₃ and Sr₂IrO₄ interlayers in Josephson structures. Barrier properties, thickness and interfaces with superconducting electrodes are central to this work.',papers[2]['url'])]
  rows=''.join(f'<div class="research-row"><div><h3>{tr(r,e)}</h3><p>{tr(br,be)}</p>{a(url,tr("Статья по теме ↗","Related paper ↗"))}</div></div>' for r,e,br,be,url in topics)
  content=heading(t['nav'][1],tr('Тонкие плёнки SrIrO₃ и Sr₂IrO₄, электронный транспорт и гетероструктуры.','SrIrO₃ and Sr₂IrO₄ thin films, electronic transport and heterostructures.'))+section('questions',tr('Направления работы','Research areas'),rows)+section('atlas',tr('В лаборатории','In the laboratory'),atlas())+section('methods',t['methods'],methods())+section('thesis',t['thesis'],thesis())
  return layout(content,[('questions',tr('Направления','Research areas')),('atlas',tr('В лаборатории','In the laboratory')),('methods',t['methods']),('thesis',t['thesis'])])
 if page=='publications':
  years=sorted({p['year'] for p in papers},reverse=True)
  intro=tr('Работы об оксидных плёнках, деформации решётки и переносе заряда. Для каждой статьи указана опубликованная версия; ранняя рукопись приведена рядом.','Papers on oxide films, lattice strain and charge transport. Each entry links to the published version, with earlier manuscripts alongside.')
  note=tr('Русские заголовки помогают ориентироваться в списке; оригинальные названия и библиографические данные приведены ниже.','Journal titles and bibliographic metadata follow the published versions.')
  return layout(heading(t['nav'][2],intro)+f'<p class="note">{note}</p><p class="bibliography-downloads">{tr("Скачать библиографию:","Download bibliography:")} <a href="/assets/publications.bib" download>BibTeX</a> · <a href="/assets/publications.ris" download>RIS</a></p><form class="filters" role="search"><div><label for="paper-search">{t["search"]}</label><input id="paper-search" type="search"></div><div><label for="paper-year">{t["year"]}</label><select id="paper-year"><option value="">{t["all"]}</option>{"".join(f"<option>{y}</option>" for y in years)}</select></div></form><p class="filter-status" role="status" aria-live="polite" data-label="{t["count"]}">{t["count"]} {len(papers)}</p><div id="papers">'+''.join(paper(p,lang,text,a) for p in papers)+f'</div><p id="no-results" hidden>{t["empty"]}</p>'+section('thesis',t['thesis'],thesis()),[('papers',tr('Статьи и тезисы','Articles & abstracts')),('thesis',t['thesis'])])
 if page=='conferences':
  intro=tr('Доклады и опубликованные материалы: от жидких кристаллов к оксидной электронике.','Talks and published proceedings: from liquid crystals to oxide electronics.')
  note=tr('Доклады, тезисы и совместные работы за 2023–2026 годы.','Talks, abstracts and collaborative contributions from 2023 to 2026.')
  content=heading(t['nav'][5],intro)+f'<p class="note">{note}</p>'
  for y in ['2026','2025','2024','2023']:
   content+=section('year-'+y,y,conferences(year=y))
  return layout(content,[('year-'+y,y) for y in ['2026','2025','2024','2023']])
 if page=='cv':
  content=heading(t['nav'][3],tr('Никита Владимирович Дубицкий. Физик, инженер ИРЭ РАН.','Nikita Vladimirovich Dubitskiy. Physicist and research engineer at IRE RAS.'))+f'<div class="cv-downloads"><a class="button" href="/assets/nikita-dubitskiy-cv-{lang}.pdf" download>{tr("Скачать CV · PDF","Download CV · PDF")}</a><a href="/assets/nikita-dubitskiy-cv-{lang}.pdf" target="_blank" rel="noopener">{tr("Открыть PDF","Open PDF")}</a></div>'+section('experience',t['experience'],f'<div class="timeline-item"><span>2023 — {t["present"]}</span><div><h3>{t["engineer"]}</h3><p>{t["institute"]}</p><p>{lab()}</p><p>{t["work"]}</p></div></div>')+section('education',t['education'],education())+section('path',tr('Как я пришёл к этой теме','How I came to this topic'),'<p>'+tr('В МИРЭА я учился по направлению «Нанотехнологии и микросистемная техника». Первые конференционные работы были связаны с жидкими кристаллами и обнаружением микропластика. Затем я перешёл к оксидным плёнкам, рентгеновской дифракции и электронному транспорту. В магистратуре ВШЭ эта работа сложилась в исследование влияния подложки на SrIrO₃.','At MIREA, I studied Nanotechnology and Microsystem Engineering. My early conference work concerned liquid crystals and microplastic detection. I then moved to oxide films, X-ray diffraction and electronic transport. During my master’s degree at HSE University, this developed into a study of substrate effects in SrIrO₃.')+'</p>')+section('recognition',t['awards'],'<ul>'+''.join('<li>'+x+'</li>' for x in t['awardlist'])+'</ul>'+nto())+section('methods',t['methods'],methods())+section('conferences',t['nav'][5],'<p>'+a(path(lang,'conferences'),tr('Темы, даты и источники докладов →','Topics, dates and sources →'))+'</p>')
  return layout(content,[('experience',t['experience']),('education',t['education']),('path',tr('Путь в науку','Research path')),('recognition',t['awards']),('methods',t['methods']),('conferences',t['nav'][5])])
 content=heading(t['nav'][4],tr('Напишите, что вы исследуете и что хотите обсудить.','Tell me what you study and what you would like to discuss.'))+section('email',tr('Быстрое письмо','Quick email'),contact_form())+section('laboratory',tr('Место работы','Affiliation'),f'<p>{t["institute"]}</p><p>{lab()}</p><p>{t["location"]}</p>')+section('profiles',t['profiles'],'<ul class="contact-profiles">'+''.join('<li>'+a(v,k+' ↗')+'</li>' for k,v in profiles.items())+'</ul>')
 return layout(content,[('email',t['email']),('laboratory',tr('Лаборатория','Laboratory')),('profiles',t['profiles'])])
